#!/bin/bash
# Task 156-w10-sort16k-hot -- meshsim sim/ WORKER10 (branch sim-w10; kit: after f6382f7, extra: uniform.keys). TIMING TASK: keep the box quiet while it runs.
# The 16K sort's hot lines (W10): perf record (cycles) on bench_sort, one thread, the counted span (one machine after
# an untimed one), built clang release + -g; perf report's top symbols, and perf annotate's lines at 0.5% or more of
# TileCtl, BigSram, Injection, Router (the four largest unit kinds: 25, 16, 16, 13% of the units' time, Quest 155),
# their run loops and deliver_link. One revision (f6382f7). ~3 min.
# From an embedded kit (sim/ at each revision named above). Writes only results/156-w10-sort16k-hot/. Scratch in /tmp, removed first
# and at the end. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/156-w10-sort16k-hot; mkdir -p "$RES"; rm -f "$RES/raw.txt"
W=/tmp/w10-156-w10-sort16k-hot; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "6deb5d303b30acef76e0183e3b303e91ee7c6ecd9762977d8094543843169481" ] || { echo "kit sha256 mismatch (want 6deb5d303b30acef76e0183e3b303e91ee7c6ecd9762977d8094543843169481)"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
KITS="after"
FAILS=0; FAIL=0
sec() { echo; echo "==== $*  [$(date +%T)]"; }
verdict() { echo "VERDICT $1: $2"; [ "$2" = PASS ] || FAIL=1; }
START=$(date +%s)
{
sec "machine (D21)"; . "$W/kit/after/sim/tools/machine.sh" "${QUEST_P_CPUS:-}" "${QUEST_E_CPUS:-}"; machine_record "$RES/machine.txt"; uptime
echo "kit: after f6382f7, extra: uniform.keys"
# Shared by W10's task bodies. run TAG CPUSET cmd...: one run under taskset (and perf stat when PERF=1: cycles,
# instructions, L1d load misses, LLC load misses, summed per core type); appends "TAG <bench line> [perf: ...]" to
# $RES/raw.txt. field NAME: a key=value field of stdin's lines.
run() {
  local tag=$1 cpus=$2; shift 2
  command -v perf > /dev/null || PERF=0
  if [ "${PERF:-0}" = 1 ]; then
    taskset -c "$cpus" perf stat -x, -e cycles,instructions,L1-dcache-load-misses,LLC-load-misses -o "$W/perf.csv" -- "$@" \
      > "$W/out.txt" 2> "$W/err.txt"
  else
    taskset -c "$cpus" "$@" > "$W/out.txt" 2> "$W/err.txt"
  fi
  local rc=$?
  local line; line=$(grep -E '^(threads|chip) ' "$W/out.txt" | tail -1)
  if [ $rc -ne 0 ] || [ -z "$line" ]; then echo "RUNFAIL $tag rc=$rc: $*"; head -5 "$W/err.txt"; FAILS=$((FAILS + 1)); return 1; fi
  local pc=""
  [ "${PERF:-0}" = 1 ] && pc=" perf: $(awk -F, '$1 ~ /^[0-9]+$/ { n=split($3,a,"/"); ev=(n>1)?a[2]:a[1]; k=(a[1]=="cpu_atom")?"atom":"core";
      v[k "_" ev]+=$1 } END { for (x in v) printf "%s=%s ", x, v[x] }' "$W/perf.csv")"
  echo "$tag $line$pc" | tee -a "$RES/raw.txt"
}
field() { grep -o "$1=[^ ]*" | cut -d= -f2; }
# med TAG FIELD: the median of FIELD over raw.txt's lines starting "TAG "
med() { grep "^$1 " "$RES/raw.txt" | field "$2" | sort -g | awk '{ a[NR]=$1 } END { if (NR) print a[int((NR+1)/2)]; else print "-" }'; }
BENCH=bench_sort
ARGS="--keys $W/kit/extra/uniform.keys --span 14838 511457 --reps 1"
SYMS="units::TileCtl::|units::BigSram::|units::Injection::|units::Router::|run_form<units::TileCtl|run_form<units::BigSram|run_form<units::Injection|deliver_link"
# Task body (WORKER10): the hot lines of any unit or framework function, from one task. perf record (cycles) on a
# bench_chip run built clang release + -g (its own build directory), then perf annotate --stdio: for each symbol whose
# name contains one of SYMS ('|'-separated), its lines at THRESH percent of the symbol or more, with the source lines
# perf interleaves. ARGS: the bench_chip arguments (default the sort's boot, one thread, 9 machines).
# For the sort: ARGS="--prog sort16k ..." SYMS="WriteEngine|Gather|..." (the units' class names).
BENCH=${BENCH:-bench_chip}            # or bench_sort (then ARGS gets --keys $W/kit/extra/uniform.keys)
ARGS=${ARGS:---prog sort --reps 9}
SYMS=${SYMS:-run_form<units::TileCore|run_form<units::Router|deliver_link<3u>|Engine::near_slot|units::Router::step|TileCore::step}
THRESH=${THRESH:-0.5}
sec "build (clang release + -g, its own directory)"
for k in $KITS; do
  ( cd "$W/kit/$k/sim" && make -j8 CC_NAME=clang MODE=release B=build/prof RELEASE="-O2 -DNDEBUG -g" build/prof/$BENCH > "$RES/build-$k.log" 2>&1 ) \
    || { tail -20 "$RES/build-$k.log"; verdict "build $k" FAIL; exit 1; }
done
P1=$(take 1 "$P_ONE")
for k in $KITS; do
  cd "$W/kit/$k/sim"
  sec "perf record: $BENCH $ARGS ($k)"
  if ! taskset -c "$P1" perf record -q -e cycles -o "$W/p.data" -- ./build/prof/$BENCH $ARGS > "$RES/run-$k.txt" 2>&1; then
    verdict "perf record ($k)" FAIL; cd - > /dev/null; continue
  fi
  perf report -i "$W/p.data" --stdio --no-children --percent-limit 0.5 --sort symbol 2>/dev/null | grep -v '^#' | grep -v '^$' | head -40 | tee "$RES/report-$k.txt"
  perf annotate -i "$W/p.data" --stdio -l 2>/dev/null > "$W/ann.txt"
  head -120 "$W/ann.txt" > "$RES/annotate-raw-head-$k.txt"            # the format, for the parse below
  # a block starts at a "Percent |" line; its symbol is the first "<name>:" line after it; lines "P : ..." with P a
  # percent of the symbol's samples; source lines (perf -l) are kept between them when a hot line follows
  awk -v syms="$SYMS" -v th="$THRESH" '
    BEGIN { n = split(syms, pat, "|") }
    /Percent \|/ { insym = 0; sym = ""; next }
    sym == "" && match($0, /<[^>]*(<[^>]*>)*[^>]*>:[ \t]*$/) {
      sym = substr($0, RSTART + 1, RLENGTH - 3); insym = 0
      for (i = 1; i <= n; i++) if (index(sym, pat[i])) insym = 1
      if (insym) { print ""; print "==== " sym }
      next
    }
    !insym { next }
    $1 ~ /^[0-9]+\.[0-9]+$/ && $2 == ":" { if ($1 + 0 >= th) { if (src != "") print "      src: " src; print; } src = ""; next }
    $1 == ":" && NF > 1 { src = $0; sub(/^[ \t]*:[ \t]*/, "", src) }
  ' "$W/ann.txt" | tee "$RES/annotate-$k.txt" | head -300
  lines=$(grep -c ' : ' "$RES/annotate-$k.txt")
  [ "$lines" -gt 0 ] && verdict "annotate found hot lines ($k: $lines)" PASS || verdict "annotate found hot lines ($k)" FAIL
  cd - > /dev/null
done
sec "done in $(($(date +%s) - START)) s"
} 2>&1 | tee "$RES/run.log"
grep '^VERDICT' "$RES/run.log" > "$RES/VERDICTS.txt"
rm -rf "$W"
grep -q ': FAIL$' "$RES/VERDICTS.txt" && exit 1
exit 0
